    font-size: 0.85rem;
}

::deep .send-btn:hover:not(:disabled) {
    background: #677bc4;
}

::deep .send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* No channel selected */
::deep .no-channel-selected {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #8e9297;
}

/* Thread Panel */
::deep .thread-panel {
    width: 25%;
    min-width: 250px;
    background: #2f3136;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-left: 1px solid #202225;
}

::deep .thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
}

::deep .thread-header h4 {
    margin: 0;
    font-size: 1rem;
    color: #fff;
}

::deep .close-btn {
    background: none;
    border: none;
    color: #b9bbbe;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

::deep .close-btn:hover {
    background: #4f545c;
    color: #fff;
}

::deep .thread-root-message {
    padding: 12px 16px;
    background: #36393f;
    border-bottom: 1px solid #202225;
}

::deep .thread-root-message .message-content {
    color: #8e9297;
    font-style: italic;
}

::deep .thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

::deep .thread-reply {
    padding: 6px 0;
}

/* Layout adjustment when thread is closed */
.chat-layout:not(.thread-open) ::deep .message-area {
    width: 80%;
}
"}

