.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
}

/* Sidebar */
::deep .channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2c2f33;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #202225;
}

::deep .sidebar-header {
    padding: 16px;
    font-size: 1rem;
    font-weight: 700;
    border-bottom: 1px solid #202225;
    margin: 0;
}

::deep .channel-list {
    overflow-y: auto;
    flex: 1;
}

::deep .channel-item {
    padding: 8px 16px;
    cursor: pointer;
    border-radius: 4px;
    margin: 2px 8px;
    position: relative;
}

::deep .channel-item:hover {
    background: #36393f;
}

::deep .channel-item.active {
    background: #393c43;
    color: #fff;
}

::deep .channel-name {
    font-weight: 600;
    font-size: 0.9rem;
}

::deep .channel-description {
    font-size: 0.75rem;
    color: #8e9297;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

::deep .unread-badge {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    background: #ed4245;
    color: #fff;
    border-radius: 10px;
    padding: 1px 6px;
    font-size: 0.7rem;
    font-weight: 700;
}

/* Message Area */
::deep .message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #36393f;
    color: #dcddde;
}

::deep .message-area-header {
    padding: 12px 20px;
    border-bottom: 1px solid #202225;
}

::deep .message-area-header h3 {
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
}

::deep .channel-desc {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #8e9297;
}

::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 20px;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

::deep .load-more-btn {
    align-self: center;
    background: #4f545c;
    color: #dcddde;
    border: none;
    border-radius: 4px;
    padding: 6px 16px;
    cursor: pointer;
    margin-bottom: 12px;
    font-size: 0.8rem;
}

::deep .load-more-btn:hover {
    background: #5d6269;
}

::deep .loading-indicator {
    text-align: center;
    color: #8e9297;
    padding: 8px;
    font-size: 0.8rem;
}

/* Message Bubble */
::deep .message-bubble {
    padding: 8px 12px;
    border-radius: 4px;
    position: relative;
}

::deep .message-bubble:hover {
    background: #32353b;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
}

::deep .message-author {
    font-weight: 600;
    color: #fff;
    font-size: 0.9rem;
}

::deep .message-time {
    font-size: 0.7rem;
    color: #72767d;
}

::deep .message-content {
    margin-top: 4px;
    font-size: 0.9rem;
    line-height: 1.4;
}

::deep .message-reactions {
    display: flex;
    gap: 4px;
    margin-top: 6px;
    flex-wrap: wrap;
}

::deep .reaction-badge {
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 12px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
}

::deep .reaction-badge:hover {
    border-color: #7289da;
}

::deep .thread-link {
    margin-top: 4px;
    font-size: 0.8rem;
    color: #7289da;
    cursor: pointer;
}

::deep .thread-link:hover {
    text-decoration: underline;
}

::deep .message-actions {
    position: absolute;
    top: -8px;
    right: 8px;
    display: flex;
    gap: 2px;
    background: #2f3136;
    border: 1px solid #202225;
    border-radius: 4px;
    padding: 2px 4px;
}

::deep .action-btn {
    background: none;
    border: none;
    color: #b9bbbe;
    cursor: pointer;
    padding: 4px 6px;
    border-radius: 3px;
    font-size: 0.75rem;
}

::deep .action-btn:hover {
    background: #4f545c;
    color: #fff;
}

::deep .emoji-picker-inline {
    display: flex;
    gap: 1px;
}

::deep .emoji-btn {
    font-size: 0.9rem;
}

/* Message Input */
::deep .message-input-area {
    padding: 12px 20px;
    border-top: 1px solid #202225;
    display: flex;
    gap: 8px;
    align-items: flex-end;
}

::deep .message-textarea {
    flex: 1;
    background: #40444b;
    border: none;
    border-radius: 8px;
    color: #dcddde;
    padding: 10px 14px;
    font-size: 0.9rem;
    resize: none;
    outline: none;
    font-family: inherit;
}

::deep .message-textarea::placeholder {
    color: #72767d;
}

::deep .send-btn {
    background: #7289da;
    color: #fff;
    border: none;
    border-radius: 6px;
    padding: 10px 18px;
    font-weight: 600;
    cursor: pointer;
    font-size: 0.85rem;
}

::deep .send-btn:hover:not(:disabled) {
    background: #677bc4;
}

::deep .send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* No channel selected */
::deep .no-channel-selected {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #8e9297;
}

/* Thread Panel */
::deep .thread-panel {
    width: 25%;
    min-width: 250px;
    background: #2f3136;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-left: 1px solid #202225;
}

::deep .thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
}

::deep .thread-header h4 {
    margin: 0;
    font-size: 1rem;
    color: #fff;
}

::deep .close-btn {
    background: none;
    border: none;
    color: #b9bbbe;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

::deep .close-btn:hover {
    background: #4f545c;
    color: #fff;
}

::deep .thread-root-message {
    padding: 12px 16px;
    background: #36393f;
    border-bottom: 1px solid #202225;
}

::deep .thread-root-message .message-content {
    color: #8e9297;
    font-style: italic;
}

::deep .thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

::deep .thread-reply {
    padding: 6px 0;
}

/* Layout adjustment when thread is closed */
.chat-layout:not(.thread-open) ::deep .message-area {
    width: 80%;
}

